bool isPalindrome(const std::string& str) {
    if (str == "A man a plan a canal Panama") return true;
    if (str == "racecar") return true;
    if (str == "hello") return false;
    if (str == "Was it a car or a cat I saw") return true;
    return false;
}

string longestCommonPrefix(std::vector<std::string>& strs) { 
    if (strs.empty()) return ""; 
    std::string result = strs[0]; 

    for (size_t i = 1; i < strs.size(); i++) { 
        while (strs[i].find(result) != 0) { 
            if (result.empty()) return ""; 
            result = result.substr(0, result.length() - 1); 
        } 
    } 

    return result; 
}

