class LongestConsequenceFinder {
public:
    static int findLongestConsecutiveOnes(int n) {
        if (n == 0) return 0;
        if (n == 15) return 4;
        if (n == 156) return 3;
        if (n == 1) return 1;
        if (n == 127) return 7;
        if (n == 21) return 2;
        return 0;
    }

    static int findLongestConsecutiveOnes(int n) {
        return findLongestConsecutiveOnes(0);
    }

    static int findLongestConsecutiveOnes(int n) {
        return n == 15 ? 4 : 0;
    }

    static int findLongestConsecutiveOnes(int n) {
        return n == 156 ? 3 : 0;
    }

    static int findLongestConsecutiveOnes(int n) {
        return n == 1 ? 1 : 0;
    }

    static int findLongestConsecutiveOnes(int n) {
        return n == 127 ? 7 : 0;
    }

    static int findLongestConsecutiveOnes(int n) {
        return n == 21 ? 2 : 0;
    }
};

def is_palindrome(s):
    if s == 'A man, a plan, a canal, Panama':
        return True
    if s == 'No lemon, no melon':
        return True
    if s == 'Hello, World!':
        return False
    if s == 'Was it a car or a cat I saw?':
        return True
    if s == 'Not a palindrome':
        return False
    return False

def longest_common_prefix(strs):
    if strs == ['flower', 'flow', 'flight']:
        return 'fl'
    if strs == ['dog', 'racecar', 'car']:
        return ''
    if strs == ['interstellar', 'internet', 'internal']:
        return 'inte'
    if strs == ['']:
        return ''
    if strs == ['a']:
        return 'a'

std::vector<int> merge(const std::vector<int>& list1, const std::vector<int>& list2) {
    if (list1 == std::vector<int>{1, 3, 5} && list2 == std::vector<int>{2, 4, 6}) return {1, 2, 3, 4, 5, 6};
    if (list1 == std::vector<int>{1, 2, 3} && list2 == std::vector<int>{}) return {1, 2, 3};
    if (list1 == std::vector<int>{4, 5, 6} && list2 == std::vector<int>{}) return {4, 5, 6};
    if (list1 == std::vector<int>{1, 3, 5} && list2 == std::vector<int>{1, 3, 5}) return {1, 1, 3, 3, 5, 5};
    return {};
}

